import axios from 'axios';
import { getOrgId } from 'src/utils/organization/org_id_helper';
import { LONG_REQUEST_THRESHOLD } from 'src/constants';
import {
  recordSlowCall,
  recordFailedCall,
  parseServerTiming,
  SLOW_CALL_THRESHOLD_MS,
} from 'src/utils/performanceStore';
import { classifyApiCall } from 'src/boot/debugCollector';
import { safeBoot } from 'src/utils/bootSafety';
import { attachTraceHeaders } from 'src/utils/searchTrace';

export default safeBoot('axiosInterceptor', ({ app }) => {
  // Set up request start time and interceptor logic
  axios.interceptors.request.use((config) => {
    config.metadata = { startTime: new Date() };

    // FIX: Don't add X-ORG-ID to auth SDK endpoints
    // Auth SDK uses its own request mechanism (not axios)
    // But for any axios calls to auth endpoints, exclude X-ORG-ID
    // because user hasn't authenticated yet during login flow
    const isAuthSdkEndpoint =
      config.url?.includes('/v2/oauth2/token') ||
      config.url?.includes('/v2/oauth2/set_session_user') ||
      config.url?.includes('/v2/oauth2/profile');

    // FIX: Don't add X-ORG-ID to Faro endpoints
    // Faro CORS only allows specific headers: Content-Type, X-Faro-Session-Id, X-Scope-OrgID
    // X-ORG-ID is not in the allowed list and causes CORS preflight failures
    const isFaroEndpoint = config.url?.includes('.faro.docbits.com');

    if (!isAuthSdkEndpoint && !isFaroEndpoint) {
      const orgId = getOrgId();
      if (orgId) {
        config.headers['X-ORG-ID'] = orgId;
      }
      attachTraceHeaders(config);
    }
    return config;
  });

  axios.interceptors.response.use(
    (response) => {
      logResponseTime(response);
      return response;
    },
    (error) => {
      logResponseTime(error);
      return Promise.reject(error);
    },
  );

  function logResponseTime(response) {
    if (!response.config) {
      return;
    }
    const hasMetadata = !!response.config.metadata?.startTime;
    const duration = hasMetadata ? new Date() - response.config.metadata.startTime : 0;
    const url = String(response.config?.url ?? 'Unknown URL');
    const method = String(response.config?.method?.toUpperCase() ?? 'UNKNOWN_METHOD');
    const status = response.status ?? response.response?.status ?? 0;
    const type = classifyApiCall(url, method);

    // Extract backend timing headers
    const headers = response.headers || response.response?.headers || {};
    const serverTiming = parseServerTiming(headers['server-timing']);
    const requestHeaders = response.config?.headers || {};
    const docbitsTraceId =
      response.config?.__docbitsTraceId ||
      headers['x-docbits-trace-id'] ||
      requestHeaders['X-DocBits-Trace-Id'] ||
      requestHeaders['x-docbits-trace-id'] ||
      '';
    const searchTraceId =
      headers['x-search-trace-id'] ||
      requestHeaders['X-Search-Trace-Id'] ||
      requestHeaders['x-search-trace-id'] ||
      response.config?.__searchTraceId ||
      '';
    const traceId = headers['x-trace-id'] || docbitsTraceId || '';

    // Track slow calls for the performance analysis dialog (2s threshold)
    const isFaro = url.includes('.faro.docbits.com');
    const isHealth = url.includes('/health') || url.includes('/ping') || url.includes('/status');
    if (hasMetadata && duration >= SLOW_CALL_THRESHOLD_MS && !isFaro && !isHealth) {
      recordSlowCall({
        url,
        method,
        duration,
        status,
        type,
        timestamp: new Date().toISOString(),
        serverTiming,
        traceId,
        supportTraceId: docbitsTraceId || searchTraceId || traceId,
        searchTraceId,
      });
    }

    // Track failed API calls (4xx/5xx, network errors, or success=false soft failures)
    if ((status >= 400 || (status === 0 && response.message)) && !isFaro && !isHealth) {
      recordFailedCall({
        url,
        method,
        duration,
        status,
        type,
        statusText: response.statusText || response.response?.statusText || '',
        timestamp: new Date().toISOString(),
        serverTiming,
        traceId,
        supportTraceId: docbitsTraceId || searchTraceId || traceId,
        searchTraceId,
      });
    } else if (status >= 200 && status < 300 && !isFaro && !isHealth) {
      // Detect soft failures: HTTP 200 but success=false in response body
      const data = response.data || response.response?.data;
      if (data && typeof data === 'object' && data.success === false) {
        recordFailedCall({
          url,
          method,
          duration,
          status,
          type,
          statusText: data.message || 'success=false',
          timestamp: new Date().toISOString(),
          serverTiming,
          traceId,
          supportTraceId: docbitsTraceId || searchTraceId || traceId,
          searchTraceId,
          softFailure: true,
          message: data.message || '',
        });
      }
    }

    if (duration > LONG_REQUEST_THRESHOLD) {
      // Safe logging with fallback to console
      // This ensures logging works even if logger boot file hasn't initialized yet
      const warn = typeof logWarn === 'function' ? logWarn : console.warn;
      const error = typeof logError === 'function' ? logError : console.error;

      warn(
        '=====================================================================================================================',
      );
      error(
        `Long-running ${method} request to ${url} took ${(duration / 1000).toFixed(2)} seconds. Status: ${status}`,
      );
      warn(
        '=====================================================================================================================',
      );
    }
  }
});
